from networkx import Graph, vertex_connectivity, max_weight_clique
import networkx as nx

G = Graph()
for i in range(10):
    G.add_node(i)

# Add edges to ensure vertex-connectivity is at least 2
for i in range(10):
    for j in range(i+1, 10):
        if i // 3 == j // 3:
            G.add_edge(i, j)

# Add edges to ensure maximum independent set size is at most 3
for i in range(0, 10, 3):
    for j in range(i, i+3):
        for k in range(j+1, i+3):
            G.add_edge(j, k)

if vertex_connectivity(G) >= 2 and len(max_weight_clique(G, weight=None)) <= 3:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
